1:import { useQuery } from '@tanstack/react-query';
2:import { getJson } from '../../api/http';
3:import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
4:import { useAsOf } from '../../session/session';
5:import { type Claim, type ClaimStatus, isOpen } from '../claims/claims';
6:import type { Person } from '../people/people';
7:import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
8:
9:/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
10: *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
11: *  due-total fixed on closing, by person id (empty while open), and whether it is soft-closed: not closed,
12: *  but with those figures fixed as when it was soft-closed, and the most OPEN or PENDING claims a person may
13: *  have in it (null for no cap), and each person's carried figure fixed with their due-total, by person id
14: *  (empty while open), and whether a steward has locked it (a locked period cannot be reopened), and its place in the order
15: *  the periods were added (higher is later). No two periods on a sheet overlap. */
16:export type Period = {
17:  name: string;
18:  from: string;
19:  to: string;
20:  closed: boolean;
21:  total: string | null;
22:  people: Record<string, string>;
23:  soft: boolean;
24:  cap: number | null;
25:  carried: Record<string, string>;
26:  locked: boolean;
27:  added: number;
28:};
29:
30:/** Whether the period's figures are fixed: it is closed or soft-closed. */
31:export const isFixed = (period: Period) => period.closed || period.soft;
32:
33:/** Under the sheet's key, so loading the sheet again re-reads its periods. */
34:export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;
35:
36:/** Every period on the sheet, by from-date. */
37:export function usePeriods(sheet: string) {
38:  const [asOf] = useAsOf();
39:  return useQuery({
40:    queryKey: asOfKey(periodsKey(sheet), asOf),
41:    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
42:    enabled: sheet !== '',
43:  });
44:}
45:
46:/** Whether the date (yyyy-MM-dd) falls in the period. */
47:export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;
48:
49:/** The period whose dates contain the date, or undefined when none does. */
50:export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
51:  return (periods ?? []).find((p) => contains(p, date));
52:}
53:
54:/** The claim's status at the end of the day (yyyy-MM-dd), as its status log records it (each line
55: *  dated the sheet's today when the change was made); null when it had not been added by then. */
56:export function statusAt(claim: Claim, date: string): ClaimStatus | null {
57:  let status: ClaimStatus | null = null;
58:  for (const line of claim.log ?? []) {
59:    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
60:    if (m && m[2] <= date) status = m[1] as ClaimStatus;
61:  }
62:  return status;
63:}
64:
65:/** Whether the claim counts toward a period: by the status it had at the end of the period's last
66: *  day it was OPEN, PENDING or SETTLED; and, as the live rules say, it is not deferred on the sheet's
67: *  today, nor (while open then and still open now, and unbound by a statement) of a person whose retirement date the sheet's today has reached. */
68:export function countsInPeriod(claim: Claim, period: Period, person: Person): boolean {
69:  const status = statusAt(claim, period.to);
70:  if (status === 'SETTLED') return true;
71:  if (status !== 'OPEN' && status !== 'PENDING') return false;
72:  return !(claim.status !== 'VOID' && claim.deferred) && (claim.stated || !isOpen(claim) || !person.retiredNow);
73:}
74:
75:/** A person's due-total for a period: once closed or soft-closed, the figure fixed then (0.00 for a person
76: *  added since); else the sum of the figures (as shown now) of their claims whose due-by falls in it
77: *  and that count by their status at the period's end, skipping n/a. */
78:export function personPeriodDue(
79:  period: Period,
80:  person: Person,
81:  claims: Claim[] | undefined,
82:  rates: Rate[] | undefined,
83:  floor: Floor,
84:  late: Late,
85:): string {
86:  if (isFixed(period)) return period.people?.[String(person.id)] ?? '0.00';
87:  return dueTotal(
88:    (claims ?? [])
89:      .filter((c) => c.personId === person.id && contains(period, c.dueBy) && countsInPeriod(c, period, person))
90:      .map((c) => claimDue(c, rates, person.grades, floor, late)),
91:  );
92:}
93:
94:/** A person's carried figure for a period: once closed or soft-closed, the figure fixed then (0.00 for a person
95: *  added since); else the sum of the figures (as shown now) of their claims that count
96: *  in it, whose due-by falls in a period ending before it starts, and that were still OPEN or PENDING at
97: *  its end by their status log, skipping n/a, with their opening balance for it (0.00 for none) added;
98: *  0.00 when nothing is carried. A closed period's fixed figure took in the opening balance as it was then. */
99:export function personPeriodCarried(
100:  period: Period,
101:  periods: Period[] | undefined,
102:  person: Person,
103:  claims: Claim[] | undefined,
104:  rates: Rate[] | undefined,
105:  floor: Floor,
106:  late: Late,
107:  opening: string,
108:): string {
109:  if (isFixed(period)) return period.carried?.[String(person.id)] ?? '0.00';
110:  const earlier = (periods ?? []).filter((p) => p.to < period.from);
111:  return dueTotal([
112:    opening,
113:    ...(claims ?? [])
114:      .filter((c) => c.personId === person.id && earlier.some((p) => contains(p, c.dueBy)))
115:      .filter((c) => {
116:        const status = statusAt(c, period.to);
117:        return (status === 'OPEN' || status === 'PENDING') && countsInPeriod(c, period, person);
118:      })
119:      .map((c) => claimDue(c, rates, person.grades, floor, late)),
120:  ]);
121:}
122:
123:/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
124:export function periodDue(
125:  period: Period,
126:  claims: Claim[] | undefined,
127:  people: Person[] | undefined,
128:  rates: Rate[] | undefined,
129:  floor: Floor,
130:  late: Late,
131:): string {
132:  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
133:}

