# POST /api/sheets/{sheetId}/people/{personId}/merge — merge a person into another on the sheet (body:
# {into, user}, `into` the other's id). Only a steward merges. The person's claims move to the other
# (numbers and dates kept, listed after the other's in the order they were added, each losing any figure a
# statement bound); their name and aliases become the other's aliases; their patrons are added to the
# other's (not the other themselves, none twice), anyone naming them as patron names the other instead
# (none twice), and their pool memberships move to the other (shares added where the other is already a
# member). Their statements, holds, watchers and contact are dropped, and they leave the sheet. Refused
# (400), storing nothing, when the user is not a steward, either person is not on the sheet, they are the
# same person, or either is retired. A stored merge is recorded in the audit file as PERSON_MERGED,
# followed by how it moved the figures.
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonMerged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithMerged
  govern: [ transaction ]
== net/officefloor/hq/app/person/ValidateMerge
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a merge by anyone but a steward. */
public class ValidateMerge {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody MergeRequest request, RoleStore roles,
            Out<MergeRequest> body) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        if (roles.find(sheetId.trim(), user) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward may merge people");
        }
        body.set(request);
    }
}
== net/officefloor/hq/app/person/MergePerson
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.crew.CrewStore;
import net.officefloor.hq.app.pool.PoolStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.statement.StatementStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Merges the person into another on the sheet, refusing the same person or either of them retired: their claims
 *  (keeping any figure a statement bound them to), statements (the other's last statement stays theirs), name and
 *  aliases, patrons, the patronage of them, their pool memberships and their crews (as lead or member) move to the other; the rest of them is
 *  dropped. */
public class MergePerson {
    public void merge(@Val MergeRequest request, @Val Person person, PersonStore people, ClaimStore claims,
            PatronStore patrons, PoolStore pools, CrewStore crews, StatementStore statements, Out<MergedInto> merged) throws InvalidSheetException {
        Person into = request.into() == null ? null : people.find(person.getSheetId(), request.into());
        if (into == null) {
            throw new InvalidSheetException("No such person to merge into");
        }
        if (into.getId() == person.getId()) {
            throw new InvalidSheetException("A person cannot be merged into themselves");
        }
        if (person.isRetired() || into.isRetired()) {
            throw new InvalidSheetException("A retired person cannot be merged");
        }
        String sheetId = person.getSheetId();
        claims.moveAll(sheetId, person.getId(), into.getId());
        statements.moveAll(sheetId, person.getId(), sheetId, into.getId());
        patrons.merge(sheetId, person.getId(), into.getId());
        pools.merge(sheetId, person.getId(), into.getId());
        crews.merge(sheetId, person.getId(), into.getId());
        people.mergeInto(person, into);
        merged.set(new MergedInto(people.find(sheetId, into.getId())));
    }
}
== net/officefloor/hq/app/person/AuditPersonMerged
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a merge: PERSON_MERGED sheet=<id> by=<user> from=<name> into=<name>, followed by how it moved the figures. */
public class AuditPersonMerged {
    public void audit(@Val MergeRequest request, @Val Person person, @Val MergedInto merged, @Val Rollup before,
            Audit audit, RollupService rollups) {
        audit.record("PERSON_MERGED sheet=" + person.getSheetId() + " by=" + request.user() + " from="
                + person.getName() + " into=" + merged.person().getName());
        rollups.record(person.getSheetId(), request.user(), before);
    }
}
